package com.lenslate.app.pipeline

import java.util.Base64
import java.util.Locale
import kotlin.math.min

/**
 * Compact offline Russian language model used by the lab's smart scan.
 *
 * The structural plausibility check in [CyrillicReadingPlausibility] counts
 * vowels and consonant runs, so a confidently recognised but invented word
 * ("ЧЕМНОТЩ", "СПЦСКЭМ") still passes it. This model adds word-level evidence:
 * a pruned trigram table trained on a Russian frequency list and a Bloom
 * lexicon of the 300 000 most frequent word forms.
 *
 * It never rewrites OCR text. It supplies a quality signal for ranking
 * competing pass readings, and a suspicion flag that makes the automated lab
 * run a deeper pass only when the fast one produced non-words.
 *
 * The data is embedded as Base64 so the model works on any thread (including
 * JVM tests) without assets, a Context or file I/O at scan time.
 */
internal object RussianLanguageModel {

    private const val LETTERS = "абвгдежзийклмнопрстуфхцчшщъыьэюя"
    private const val BOUNDARY = '^'
    private const val ALPHABET = LETTERS + BOUNDARY
    private const val N = 33

    private const val MIN_WORD_LENGTH = 3
    private const val MAX_WORD_LENGTH = 40
    private const val MIN_NEAR_WORD_LENGTH = 5
    private const val MIN_NEAR_CANDIDATE_LENGTH = 4
    private const val MAX_WORD_WEIGHT = 12

    // Mean trigram cost (0 = certain, 1 = impossible). The thresholds were
    // calibrated on the lab pages: real rare words land at 0.19..0.27, while
    // OCR inventions with a plausible vowel pattern land at 0.30..0.50.
    private const val MIN_WORD_COST = 0.17f
    private const val MAX_WORD_COST = 0.46f
    private const val MIN_UNKNOWN_QUALITY = 0.15f
    private const val NEAR_CORRECTION_QUALITY = 0.62f
    private const val SUSPECT_WORD_COST = 0.30f
    private const val NEAR_COST_TOLERANCE = 0.02f
    private const val MAX_NEAR_TRIGRAM_COST = 0.50f
    private const val MAX_TRIGRAM_COST = 0.72f

    private const val BLOOM_BITS = 2_475_528
    private const val BLOOM_HASHES = 7

    // Print-script pairs that actually get confused by Tesseract. Transpositions
    // and arbitrary substitutions produced a 20% false-correction rate on rare
    // dictionary words, so only conservative one-character corrections are used,
    // and only as a suspicion signal.
    private val CONFUSIONS: Map<Char, String> = mapOf(
        'а' to "оеия",
        'о' to "асе",
        'е' to "иа",
        'и' to "еый",
        'й' to "и",
        'ш' to "щ",
        'щ' to "ш",
        'с' to "ое",
        'з' to "в",
        'в' to "зб",
        'п' to "н",
        'н' to "п",
        'ь' to "ъ",
        'ъ' to "ь",
        'б' to "в",
        'ц' to "ч",
        'ч' to "ц",
        'ж' to "ш",
        'ы' to "и",
        'я' to "а",
    )

    private val trigramTable: ByteArray by lazy {
        Base64.getDecoder().decode(TRIGRAM_DATA)
    }

    private val bloom: ByteArray by lazy {
        Base64.getDecoder().decode(BLOOM_DATA)
    }

    fun normalize(text: String): String =
        text.lowercase(Locale.ROOT).replace('ё', 'е')

    /** Lowercased Cyrillic words of at least three letters. */
    fun words(text: String): List<String> {
        val normalized = normalize(text)
        val result = ArrayList<String>()
        var start = -1
        for (index in normalized.indices) {
            if (normalized[index] in LETTERS) {
                if (start < 0) start = index
            } else if (start >= 0) {
                if (index - start >= MIN_WORD_LENGTH) result += normalized.substring(start, index)
                start = -1
            }
        }
        if (start >= 0 && normalized.length - start >= MIN_WORD_LENGTH) {
            result += normalized.substring(start)
        }
        return result
    }

    /**
     * Average word support, weighted towards long words and capped by the
     * weakest word so one invented term cannot hide behind short prepositions.
     */
    fun lexicalScore(text: String): Float {
        val words = words(text)
        if (words.isEmpty()) return 1f
        var weighted = 0f
        var weightSum = 0f
        var weakest = 1f
        words.forEach { word ->
            val quality = wordQuality(word)
            val weight = min(word.length, MAX_WORD_WEIGHT).toFloat()
            weighted += quality * weight
            weightSum += weight
            if (quality < weakest) weakest = quality
        }
        if (weightSum <= 0f) return 1f
        return (0.7f * (weighted / weightSum) + 0.3f * weakest).coerceIn(0f, 1f)
    }

    fun isSuspectReading(text: String): Boolean =
        words(text).any(::isSuspectWord)

    fun suspectWords(text: String): List<String> =
        words(text).filter(::isSuspectWord).distinct()

    /**
     * A word is suspect when it is absent from the lexicon and either its
     * trigrams are improbable or it is one print-confusion away from a known
     * word ("ПОДЛОЖКИЁ" -> "ПОДЛОЖКИ", "ЯРКАСТИ" -> "ЯРКОСТИ").
     */
    fun isSuspectWord(word: String): Boolean {
        val normalized = normalize(word)
        if (!isScoredWord(normalized)) return false
        if (isKnownWord(normalized)) return false
        return wordCost(normalized) >= SUSPECT_WORD_COST || hasNearCorrection(normalized)
    }

    /**
     * 0..1 support for one word. Known word forms are certain; unknown words
     * keep a smooth score so rare but valid vocabulary is not treated as noise.
     */
    fun wordQuality(word: String): Float {
        val normalized = normalize(word)
        if (!isScoredWord(normalized)) return 1f
        if (isKnownWord(normalized)) return 1f
        val cost = wordCost(normalized)
        val mapped = ((MAX_WORD_COST - cost) / (MAX_WORD_COST - MIN_WORD_COST)).coerceIn(0f, 1f)
        var quality = MIN_UNKNOWN_QUALITY + (1f - MIN_UNKNOWN_QUALITY) * mapped
        if (hasNearCorrection(normalized)) quality = min(quality, NEAR_CORRECTION_QUALITY)
        return quality
    }

    /** Conservative one-edit candidates from the print-confusion set. */
    internal fun nearCorrections(word: String): List<String> {
        val normalized = normalize(word)
        if (!isScoredWord(normalized) || normalized.length < MIN_NEAR_WORD_LENGTH) return emptyList()
        if (isKnownWord(normalized)) return emptyList()
        val original = shape(normalized)
        val found = LinkedHashSet<String>()
        fun consider(candidate: String) {
            if (candidate.length !in MIN_NEAR_CANDIDATE_LENGTH..MAX_WORD_LENGTH) return
            if (candidate.length < normalized.length - 1 ||
                candidate.length > normalized.length + 1
            ) {
                return
            }
            if (!isKnownWord(candidate)) return
            val candidateShape = shape(candidate)
            if (candidateShape.mean > original.mean + NEAR_COST_TOLERANCE) return
            if (candidateShape.max > MAX_NEAR_TRIGRAM_COST || candidateShape.rare > 0) return
            found += candidate
        }
        consider(normalized.substring(1))
        consider(normalized.dropLast(1))
        for (index in normalized.indices) {
            val replacements = CONFUSIONS[normalized[index]] ?: continue
            replacements.forEach { replacement ->
                consider(
                    normalized.substring(0, index) + replacement + normalized.substring(index + 1),
                )
            }
        }
        return found.toList()
    }

    internal fun wordCost(word: String): Float {
        val normalized = normalize(word)
        if (!isScoredWord(normalized)) return 1f
        return shape(normalized).mean
    }

    /**
     * Lexicon hit confirmed by trigram shape. The Bloom filter admits a small
     * share of invented strings ("ченнотщ"); a caller that searches arbitrary
     * edit neighbourhoods must not treat those hits as real words.
     */
    internal fun isSolidWord(word: String): Boolean {
        val normalized = normalize(word)
        if (!isScoredWord(normalized) || !isKnownWord(normalized)) return false
        val candidate = shape(normalized)
        return candidate.max <= MAX_NEAR_TRIGRAM_COST && candidate.rare == 0
    }

    fun isKnownWord(word: String): Boolean {
        val normalized = normalize(word)
        if (!isScoredWord(normalized)) return false
        val first = fnv1a(normalized)
        val second = sdbm(normalized) or 1L
        for (hash in 0 until BLOOM_HASHES) {
            val bit = ((first + hash * second) % BLOOM_BITS).toInt()
            val mask = 1 shl (bit and 7)
            if (bloom[bit ushr 3].toInt() and mask == 0) return false
        }
        return true
    }

    private fun hasNearCorrection(normalized: String): Boolean =
        normalized.length >= MIN_NEAR_WORD_LENGTH && nearCorrections(normalized).isNotEmpty()

    private fun isScoredWord(normalized: String): Boolean =
        normalized.length in MIN_WORD_LENGTH..MAX_WORD_LENGTH &&
            normalized.all { it in LETTERS }

    private data class WordShape(val mean: Float, val max: Float, val rare: Int)

    private fun shape(word: String): WordShape {
        val sequence = BOUNDARY + word + BOUNDARY
        var total = 0
        var maximum = 0
        var rare = 0
        for (index in 2 until sequence.length) {
            val first = ALPHABET.indexOf(sequence[index - 2])
            val second = ALPHABET.indexOf(sequence[index - 1])
            val third = ALPHABET.indexOf(sequence[index])
            if (first < 0 || second < 0 || third < 0) return WordShape(1f, 1f, Int.MAX_VALUE)
            val cost = trigramTable[(first * N + second) * N + third].toInt() and 0xFF
            total += cost
            if (cost > maximum) maximum = cost
            if (cost > (MAX_TRIGRAM_COST * 255f).toInt()) rare++
        }
        val count = sequence.length - 2
        if (count <= 0) return WordShape(1f, 1f, 0)
        return WordShape(
            mean = total.toFloat() / count / 255f,
            max = maximum / 255f,
            rare = rare,
        )
    }

    private fun fnv1a(word: String): Long {
        var hash = 0x811C9DC5.toInt()
        word.toByteArray(Charsets.UTF_8).forEach { byte ->
            hash = hash xor (byte.toInt() and 0xFF)
            hash *= 16777619
        }
        return hash.toLong() and 0xFFFFFFFFL
    }

    private fun sdbm(word: String): Long {
        var hash = 0
        word.toByteArray(Charsets.UTF_8).forEach { byte ->
            hash = hash * 131 + (byte.toInt() and 0xFF)
        }
        return hash.toLong() and 0xFFFFFFFFL
    }

    private const val TRIGRAM_DATA =
        ""

    private val BLOOM_DATA: String =
        arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ).joinToString("")
}
